Here's how to use the Fetch API to handle multiple concurrent requests in JavaScript:

```javascript
// Method 1: Promise.all (all requests, fail if any fails)
async function fetchMultipleConcurrently(urls) {
    try {
        const promises = urls.map(url => 
            fetch(url).then(response => {
                if (!response.ok) throw new Error(`HTTP ${response.status}: ${url}`);
                return response.json();
            })
        );
        const results = await Promise.all(promises);
        return results;
    } catch (error) {
        console.error('One or more requests failed:', error);
        throw error;
    }
}

// Usage:
const urls = [
    'https://api.example.com/users',
    'https://api.example.com/posts',
    'https://api.example.com/comments'
];
const [users, posts, comments] = await fetchMultipleConcurrently(urls);

// Method 2: Promise.allSettled (all requests, don't fail on errors)
async function fetchAllSettled(urls) {
    const promises = urls.map(url =>
        fetch(url).then(res => res.ok ? res.json() : { error: `HTTP ${res.status}` })
            .catch(err => ({ error: err.message }))
    );
    return Promise.allSettled(promises);
}

// Method 3: Batch with concurrency limit
async function fetchWithConcurrencyLimit(urls, limit = 3) {
    const results = [];
    const executing = new Set();

    for (const url of urls) {
        const promise = fetch(url).then(res => res.json());
        results.push(promise);
        executing.add(promise);

        promise.finally(() => executing.delete(promise));

        if (executing.size >= limit) {
            await Promise.race(executing);
        }
    }

    return Promise.all(results);
}
```

Use `Promise.all()` when all requests must succeed, `Promise.allSettled()` when individual failures are acceptable, and a concurrency limiter to avoid overwhelming the server or browser connection limits.
